/* Signature Basque Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aitoretxe": "From Aitor + etxe (house).", "Maiteder": "From maite (beloved) + eder (beautiful): 'beautiful beloved'.", "Inigotxo": "From Inigo + -txo (diminutive).", "Aneeder": "From Ane + eder (beautiful).", "Koldobika": "Signature-style masculine name.", "Edurnezuri": "From Edurne + zuri (white): 'white snow'.", "Maitederetxe": "Signature house-name surname: 'house of the beautiful beloved'.", "Edurnezurieta": "Signature house-name surname.", "Aitorbidea": "From bide (way): Signature surname, 'Aitor's way'.", "Inigolarrea": "Signature house-name surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aitoretxe';
console.log(lookup(q));

